/* eslint-disable max-len, no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var isWebAssemblyMemory = require( '@stdlib/assert/is-wasm-memory' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherits = require( '@stdlib/utils/inherit' );
var WasmModule = require( '@stdlib/wasm/module-wrapper' );
var format = require( '@stdlib/string/format' );
var wasmBinary = require( './binary.js' );


// MAIN //

/**
* WebAssembly module wrapper constructor.
*
* @constructor
* @param {Object} memory - WebAssembly memory instance
* @throws {TypeError} must provide a WebAssembly memory instance
* @returns {Module} module instance
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var zeros = require( '@stdlib/array/zeros' );
* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var dmskmax = new Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* dmskmax.initializeSync();
*
* // Specify a vector length:
* var N = 5;
*
* // Define pointers (i.e., byte offsets) for storing the input array and mask:
* var xptr = 0;
* var mptr = N * bytesPerElement( 'float64' );
*
* // Write array values to module memory:
* dmskmax.write( xptr, oneTo( N, 'float64' ) );
* dmskmax.write( mptr, zeros( N, 'uint8' ) );
*
* // Perform computation:
* var v = dmskmax.main( N, xptr, 1, mptr, 1 );
* // returns 5.0
*/
function Module( memory ) {
	if ( !( this instanceof Module ) ) {
		return new Module( memory );
	}
	if ( !isWebAssemblyMemory( memory ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a WebAssembly memory instance. Value: `%s`.', memory ) );
	}
	// Call the parent constructor:
	WasmModule.call( this, wasmBinary, memory, {
		'env': {
			'memory': memory
		}
	});

	return this;
}

// Inherit from the parent constructor:
inherits( Module, WasmModule );

/**
* Computes the maximum value of a double-precision floating-point strided array according to a mask.
*
* @name main
* @memberof Module.prototype
* @readonly
* @type {Function}
* @param {PositiveInteger} N - number of indexed elements
* @param {NonNegativeInteger} xptr - input array pointer (i.e., byte offset)
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} mptr - mask array pointer (i.e., byte offset)
* @param {integer} strideMask - `mask` stride length
* @returns {number} maximum value
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var zeros = require( '@stdlib/array/zeros' );
* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var dmskmax = new Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* dmskmax.initializeSync();
*
* // Specify a vector length:
* var N = 5;
*
* // Define pointers (i.e., byte offsets) for storing the input array and mask:
* var xptr = 0;
* var mptr = N * bytesPerElement( 'float64' );
*
* // Write array values to module memory:
* dmskmax.write( xptr, oneTo( N, 'float64' ) );
* dmskmax.write( mptr, zeros( N, 'uint8' ) );
*
* // Perform computation:
* var v = dmskmax.main( N, xptr, 1, mptr, 1 );
* // returns 5.0
*/
setReadOnly( Module.prototype, 'main', function dmskmax( N, xptr, strideX, mptr, strideMask ) {
	return this._instance.exports.stdlib_strided_dmskmax( N, xptr, strideX, mptr, strideMask );
});

/**
* Computes the maximum value of a double-precision floating-point strided array according to a mask using alternative indexing semantics.
*
* @name ndarray
* @memberof Module.prototype
* @readonly
* @type {Function}
* @param {PositiveInteger} N - number of indexed elements
* @param {NonNegativeInteger} xptr - input array pointer (i.e., byte offset)
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting `x` index
* @param {NonNegativeInteger} mptr - mask array pointer (i.e., byte offset)
* @param {integer} strideMask - `mask` stride length
* @param {NonNegativeInteger} offsetMask - starting `mask` index
* @returns {number} maximum value
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var zeros = require( '@stdlib/array/zeros' );
* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var dmskmax = new Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* dmskmax.initializeSync();
*
* // Specify a vector length:
* var N = 5;
*
* // Define pointers (i.e., byte offsets) for storing the input array and mask:
* var xptr = 0;
* var mptr = N * bytesPerElement( 'float64' );
*
* // Write array values to module memory:
* dmskmax.write( xptr, oneTo( N, 'float64' ) );
* dmskmax.write( mptr, zeros( N, 'uint8' ) );
*
* // Perform computation:
* var v = dmskmax.ndarray( N, xptr, 1, 0, mptr, 1, 0 );
* // returns 5.0
*/
setReadOnly( Module.prototype, 'ndarray', function dmskmax( N, xptr, strideX, offsetX, mptr, strideMask, offsetMask ) {
	return this._instance.exports.stdlib_strided_dmskmax_ndarray( N, xptr, strideX, offsetX, mptr, strideMask, offsetMask );
});


// EXPORTS //

module.exports = Module;
